import json, csv
from pathlib import Path

OUT=Path(__file__).parent
talks=[]; items=[]; problems=[]; corrections=[]; areas={}

def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))

def item(record,pages,kind,title,notes,statement,reconstruction,cls,fate,status,refs=(),literal='correct with missing hypotheses',match='exact',verification='read the result',confidence='high',problem='',speaker=None,area='Algebraic K-theory',development='annotated'):
    n=sum(i['record']==record for i in items)+1
    ident=f'1971-{record}.{n}'
    d=dict(id=ident,record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of November 2026: '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth='',refs=list(refs),confidence=confidence)
    if speaker:d['speaker']=speaker
    items.append(d); areas[ident]=area
    return ident

def corr(page,place,reads,correct,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=correct,evidence=evidence,applies_to=applies,type=typ))

def save():
    for name,obj in [('talks',talks),('items',items),('problems',problems),('areas',areas)]:
        (OUT/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(244,'1971-11-15','V. I. Arnold','P000394','An unidentified characteristic invariant of a complex foliation',r'''The final paragraph of P000394 is explicitly headed Arnold. It concerns the foliation associated with a rational differential equation on the complex projective plane and asks for a geometric, possibly integral or rational, interpretation of an unnamed invariant. The request to recover rotation numbers suggests characteristic-class methods, but neither a class nor an evaluation cycle is specified. The preceding Bott discussion belongs to record 243. The catalogue span P000393--P000396 therefore substantially overstates the identifiable Arnold material.''')
item(244,'P000394','question','Geometric meaning and arithmetic of an unnamed foliation invariant',r'''Arnold writes \(dw/dz=P(z,w)/Q(z,w)\), describes a foliation on \(\mathbb{CP}^{2}\) away from several points, and mentions an invariant on a three-dimensional complex manifold described as ``point--vector''. He asks for its geometric characterization and integrality or rationality.''',r'''The equation, after homogenization and removal of its singular locus, determines a holomorphic line distribution on an open subset of \(\mathbb{CP}^{2}\). The notes do not specify the auxiliary threefold, the characteristic cocycle, its degree, a cycle on which to evaluate it, or its normalization. Consequently no definite integrality or rationality assertion can be extracted.''',r'''The interpretation as a holomorphic line distribution is standard reconstruction. Identifying the threefold with a particular frame bundle, or the invariant with a Bott or Godbillon--Vey class, would add information absent from the notebook.''','F',r'''Targeted searches combining Arnold, the 1971 date, foliation invariants, rotation numbers, projective plane, and rationality did not identify an exact publication. The thematic proximity to characteristic classes does not establish a match.''',r'''unidentified from the surviving statement. This is not evidence that a well-defined problem remains open; recovering the actual cocycle is prerequisite to further work.''',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',area='Foliations and characteristic classes')
item(244,'P000394','problem','Recovering rotation numbers from the proposed invariant',r'''The final exercise asks to define rotation numbers as invariants of the same kind, and the preceding sentence calls the construction a generalization of Poincar\'e rotation numbers.''',r'''For comparison, an orientation-preserving circle homeomorphism \(f\), with lift \(F:\mathbb R\to\mathbb R\) satisfying \(F(x+1)=F(x)+1\), has rotation number \(\rho(f)=\lim_{n\to\infty}(F^n(x)-x)/n\pmod{\mathbb Z}\). The requested realization of this number by the unnamed foliation invariant is not specified well enough to formulate an equivalence.''',r'''The displayed modern definition is supplied solely to distinguish the classical invariant from the unidentified proposed realization. It is not claimed to be the notebook's missing construction.''','F',r'''The classical rotation number predates the seminar, but a publication matching the proposed characteristic-class realization was not identified by the searches recorded in the research log. No cross-year problem identifier was reused merely because earlier foliation items mention \(\mathbb{CP}^{2}\).''',r'''the exercise's intended map from the auxiliary geometry to \(\mathbb R/\mathbb Z\) remains unidentifiable in these notes.''',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',area='Dynamical systems')
save()

talk(245,'','-','P000395','Year heading: 1972',r'''This is the catalogue's year-divider record, not an additional mathematical talk. The next explicit notebook heading is ``14 February. L. Vaserstein'' at the top of P000395. The assigned page is the location of this transition; it does not transfer Arnold's preceding paragraph or Vaserstein's ensuing mathematics to the heading.''',kind='heading')
save()

talk(246,'1972-02-14','L. N. Vaserstein','P000395-P000399','Quadratic form parameters and the beginnings of hermitian K-theory',r'''Vaserstein develops quadratic forms over rings with involution, including the form parameter needed in characteristic two, hyperbolic forms, Grothendieck--Witt and Witt groups, and stable classical groups. Examples over fields and the integers lead to remarks about classification and group rings. The final page introduces Steinberg-type central extensions and a simplicial higher-theory programme. The identifiable block starts at the dated heading on P000395 and ends before Kazhdan's heading on P000400. Several assertions are correct only after separating nonsingular forms, stable equivalence, and isometry classes.''')
item(246,'P000395','definition','Quadratic polynomials, involutions, and twisted duals',r'''The talk begins with \(q(x)=\sum a_{ij}x_ix_j\) over a commutative ring, and says that when \(2\) is invertible one may use symmetric matrices uniquely. Over a ring with involution it uses \(f(u\mu,v\lambda)=\mu^*f(u,v)\lambda\), and corrects the left/right module description of \(V^*=\operatorname{Hom}_A(V,A)\).''',r'''For an associative unital ring \(A\) with anti-involution \(*\), give \(V^*\) the right action \((f\cdot a)(v)=a^*f(v)\). Then right-linear maps \(L:V\to V^*\) correspond to sesquilinear pairings \(b(u,v)=L(u)(v)\). Over a commutative ring with \(2\in A^\times\), formal homogeneous quadratic polynomials on \(A^n\) have unique symmetric coefficient matrices; arbitrary polynomial functions over a finite ring need not determine their polynomial expressions.''',r'''The twisted right action makes the notebook's successive corrections coherent. The qualification ``formal polynomial'' avoids an unnecessary assertion about polynomial functions.''','E',r'''These are the algebraic conventions underlying the form-ring theory, already used before the talk in Vaserstein's 1970 paper. A precise modern statement appears in \citet[\S1]{bakvavilov2000structure}.''',r'''standard definitions. The crossed-out module adjectives are not evidence for a different duality convention.''',refs=['vaserstein1970stabilization','bakvavilov2000structure'],area='Hermitian K-theory')
item(246,'P000396','definition','The form parameter and quadratic forms as a quotient',r'''A central \(\varepsilon\) satisfies \(\varepsilon\varepsilon^*=1\), and an additive subgroup \(\Lambda\) lies between \(\{x-\varepsilon x^*\}\) and \(\{x=-\varepsilon x^*\}\), with \(a^*\Lambda a\subseteq\Lambda\). Quadratic forms are sesquilinear forms modulo the subgroup defined by \(X=-\varepsilon X^*\) and \(X(v,v)\in\Lambda\).''',r'''Fix \((A,*,\varepsilon,\Lambda)\) with precisely those conditions. On a right \(A\)-module \(V\), identify sesquilinear forms \(Q,Q'\) when \(X=Q-Q'\) satisfies \(X(u,v)+\varepsilon X(v,u)^*=0\) and \(X(v,v)\in\Lambda\) for all \(u,v\). This quotient retains both the associated \(\varepsilon\)-hermitian pairing and the diagonal refinement modulo \(\Lambda\).''',r'''The matrix star is interpreted as conjugate transpose; otherwise the displayed quotient has no invariant meaning.''','E',r'''The framework is that of Bak's form rings, whose pre-1972 origin is documented in \citet[introduction and \S1]{bakvavilov2000structure}. The latter gives the exact bounds on \(\Lambda\), the conjugation condition, and the corresponding quadratic module.''',r'''established form-ring language, particularly essential when \(2\) is not invertible.''',refs=['bakvavilov2000structure'],literal='correct',area='Hermitian K-theory')
item(246,'P000396','claim','Hermitianization and the failure of the diagonal alone at maximal parameter',r'''The notes define \((u,v)_q=Q(u,v)+\varepsilon Q(v,u)^*\) and \(|u|_q=Q(u,u)+\Lambda\). The final line says that for maximal \(\Lambda\) the quadratic form can be recovered from its \(|u|_q\), with ``linearization'' in parentheses.''',r'''Both \(b_q\) and \(q_\Lambda\) are independent of the representative. At \(\Lambda=\Lambda_{\max}\), the quotient quadratic form is determined by \(b_q\), not generally by \(q_\Lambda\). For a field with trivial involution, \(\varepsilon=-1\), and \(\Lambda=A\), every diagonal refinement takes values in \(A/\Lambda=0\), while nonzero alternating pairings exist.''',r'''The replacement of the diagonal expression by the hermitianized pairing is a mathematical emendation. The counterexample diagnoses the literal assertion without attributing it to the speaker's intended formulation.''','E',r'''The two pieces of data and their relation are explicit in \citet[\S1, especially Lemma 1.1]{bakvavilov2000structure}. The scan confirms the diagonal symbol in the disputed sentence; it is not an English translation error.''',r'''the corrected statement is standard; the displayed maximal-parameter assertion is false literally.''',refs=['bakvavilov2000structure'],literal='false as written',match='partial',area='Hermitian K-theory')
item(246,'P000397','construction','Hyperbolic quadratic modules and nonsingularity',r'''The example is called Hamiltonian or hyperbolic: \(H(U)=U\oplus U^*\), with a representative \(Q(u+f,u'+f')=f(u')\). A triangular matrix and the alternating matrix \(\left(\begin{smallmatrix}0&1\\-1&0\end{smallmatrix}\right)\) are displayed. Nonsingularity means that the induced map to the dual is an isomorphism.''',r'''For finite projective \(U\), the evaluation pairing defines a hyperbolic \(\Lambda\)-quadratic module on \(U\oplus U^*\). With the compatible ordering of summands, its hermitianized matrix is \(\left(\begin{smallmatrix}0&I\\\varepsilon I&0\end{smallmatrix}\right)\), up to exchanging the two blocks. The alternating matrix in the notes is the specialization \(\varepsilon=-1\).''',r'''Finite projectivity supplies the canonical bidual isomorphism and hence nonsingularity. The sign is restored as a parameter rather than silently fixing the entire talk to the symplectic case.''','E',r'''See \citet[\S1, hyperbolic quadratic module]{bakvavilov2000structure}; Vaserstein's own earlier treatment of stable unitary and orthogonal groups is \citet{vaserstein1970stabilization}.''',r'''standard hyperbolic construction; the displayed minus sign cannot represent all the form parameters introduced on P000396.''',refs=['bakvavilov2000structure','vaserstein1970stabilization'],area='Hermitian K-theory')
item(246,'P000397','definition','Grothendieck--Witt group versus Witt quotient',r'''Nonsingular forms on finite projective modules form a semigroup under orthogonal sum. Its group completion is first called the Witt group, then explicitly corrected to Witt--Grothendieck; the Witt group is the quotient by Hamiltonian forms. The notation is \(K_0O(A)\), with the form parameters suppressed.''',r'''The group completion of isometry classes of nonsingular \(\Lambda\)-quadratic forms is \(GW_0(A,*,\varepsilon,\Lambda)\). Its quotient by the subgroup generated by hyperbolic forms is the corresponding Witt group. Witt cancellation, in its familiar form, holds for finite-dimensional nonsingular quadratic spaces over a field of characteristic different from two; analogous involutive versions require their own hypotheses.''',r'''The notebook's correction is retained. The characteristic restriction is supplied for the classical cancellation statement, without asserting an unrestricted theorem for every parameter over every division ring.''','E',r'''These are classical distinctions in the theory of forms, rather than a new higher \(K\)-theory result. The stable group framework had already appeared in \citet{vaserstein1970stabilization}; \citet[\S1]{bakvavilov2000structure} fixes the parameter conventions used here.''',r'''established. Conflating group completion with the hyperbolic quotient would change subsequent examples.''',refs=['vaserstein1970stabilization','bakvavilov2000structure'],match='partial',verification='indirect',area='Quadratic forms')
item(246,'P000397','theorem','Hyperbolic complements and the finiteness restriction',r'''Theorem 1 says that every finite projective module with a quadratic form is an orthogonal summand of \(H(A^n)\). A following remark says that allowing cancellation by arbitrary modules makes the group zero, illustrated by \(a+b+a+b+\cdots\).''',r'''For a nonsingular quadratic module \((P,q)\), the diagonal in \((P,q)\perp(P,-q)\) is a lagrangian, giving a hyperbolic module; choosing \(P\oplus P'\cong A^n\) supplies a finite hyperbolic complement. If the category instead admits countable orthogonal sums, the isomorphism \(X\oplus\bigoplus_{m\ge1}X\cong\bigoplus_{m\ge1}X\) forces \([X]=0\) in its group completion.''',r'''Nonsingularity is inherited from the immediately preceding definition and is indispensable: a singular form cannot be a nonsingular orthogonal summand of a nonsingular form. The infinite-sum remark is an Eilenberg swindle, not a statement that ordinary finite-projective Witt groups vanish.''','E',r'''Both arguments belong to the standard stable algebraic framework; compare the finite-projective definitions in \citet[\S12]{bass1964stable}. No new general vanishing theorem is being announced.''',r'''valid with the stated category restrictions. The finite-projective and arbitrary-module group completions must remain distinct.''',refs=['bass1964stable'],match='partial',verification='indirect',area='Quadratic forms')
item(246,'P000398','claim','Field and integral examples: stable invariants are not complete isometry invariants',r'''Examples over a field with \(\varepsilon=\pm1\) are followed by \(K_0O(A)=\mathbb Z\). Over \(\mathbb Z\), the notes discuss dimension and signature, and for \(\varepsilon=-1\) distinguish \(\Lambda=\mathbb Z\) from \(2\mathbb Z\), mentioning the Arf invariant.''',r'''Nonsingular alternating forms over a field are classified by their even dimension, yielding \(GW_0^{\mathrm{alt}}\cong\mathbb Z\). The corresponding blanket statement for symmetric forms is false: over \(\mathbb R\), positive and negative indices give \(GW_0(\mathbb R)\cong\mathbb Z^2\). Integral rank and signature do not classify definite even unimodular lattices up to isometry. For a unimodular alternating integral pairing, a quadratic refinement modulo two induces a nonsingular quadratic space on the reduction modulo two, whose Arf invariant distinguishes its two symplectic equivalence classes in positive even dimension.''',r'''The examples are separated by parameter and equivalence relation. The Arf statement is about the induced mod-two refinement, not an invariant of the underlying alternating bilinear pairing alone.''','E',r'''The form-parameter distinction is explicit in \citet[\S1]{bakvavilov2000structure}. The general framework predates the talk. The Arf discussion is thematically related to earlier occurrence 1970-228.2, but the notebook poses no recurrent question requiring a problem-index identification.''',r'''the corrected examples are standard; the universal \(\mathbb Z\) claim and an unrestricted isometry classification by rank and signature are false.''',refs=['bakvavilov2000structure'],literal='false as written',match='partial',verification='indirect',area='Quadratic forms')
item(246,'P000398','question','An unspecified K-group of a finite group ring',r'''The notes say that little is known for \(A=\mathbb Z[g]\), and give \(g=\mathbb Z_p\times\mathbb Z_q\) as an example where \(K_0\) is unknown.''',r'''A precise computation would require specifying whether \(K_0\) means ordinary projective \(K_0\), its reduced class group, or the hermitian group \(K_0O\) of this talk; in the last case one must also fix the group-ring involution, \(\varepsilon\), and \(\Lambda\). The roles and assumptions on \(p,q\) are not supplied.''',r'''No particular group-ring conjecture is substituted for these omitted choices. In particular, a theorem about projective ideal class groups would not automatically settle the hermitian question.''','F',r'''Searches of Vaserstein's publications and the surrounding algebraic \(K\)-theory literature did not identify a unique computation with these parameters. The supplied prior index contains no exact recurrence.''',r'''the historical ``unknown'' cannot be converted into a present-day open-problem claim without identifying the functor.''',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',area='Group rings')
item(246,'P000398','remark','The numerical claim about 32-variable unimodular forms',r'''A numerical aside mentions approximately \(80\cdot10^6\) forms in 32 variables with determinant one.''',r'''An enumeration requires at least specifying integral versus rational equivalence, positive definiteness, parity, and whether the number is an exact count or a lower bound. Determinant one and rank 32 by themselves do not specify the class being counted.''',r'''The remark is kept as a numerical historical assertion; no exact enumeration or modern lower bound is inferred from its magnitude.''','F',r'''No exact source for this number with the necessary hypotheses was identified in the searches recorded in the log. It must not be presented as a verified enumeration theorem.''',r'''unverified numerical aside; no claim is made that the relevant lattice enumeration problem remains unresolved.''',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',area='Integral lattices')
item(246,'P000398','theorem','Matrix-ring invariance and the choice of duality',r'''The notes record equality of the \(K\)-groups of \(A\) and of its matrix rings.''',r'''For a unital associative ring and \(r\ge1\), Morita equivalence yields \(K_n(M_r(A))\cong K_n(A)\) for ordinary algebraic \(K\)-theory. In a hermitian version the equivalence must transport the involution, duality, and form parameter; an arbitrary unrelated involution on the matrix ring is not covered.''',r'''Ordinary Morita invariance is the secure statement. The duality requirement prevents importing it unchanged into every hermitian theory mentioned in the talk.''','E',r'''The low-degree stable-algebra form is already in \citet[\S\S12--14]{bass1964stable}; the higher-theory comparison is subsequently incorporated into \citet{vaserstein1973foundations}.''',r'''established, with the stated compatibility qualification for forms.''',refs=['bass1964stable','vaserstein1973foundations'],match='partial',area='Algebraic K-theory')
item(246,'P000398-P000399','definition','Stable orthogonal groups and hermitian K1',r'''The stable group \(O(A)\) is formed from automorphism groups of \(H(A^n)\); \(K_1O(A)\) is its abelianization, with an elementary subgroup playing the role of commutators.''',r'''Fix the form ring and use stabilization by a hyperbolic plane. The stable unitary group \(U(A,\Lambda)\) has the stable elementary subgroup \(EU(A,\Lambda)\); under the standard stable form-ring conventions their quotient is hermitian \(K_1\). Assertions about a single finite-rank group require separate stability bounds and cannot be read off from this direct limit.''',r'''The letter \(O\) is understood in the notebook's broad parameter-dependent sense, including symplectic and unitary specializations, rather than only the usual orthogonal group of a field.''','E',r'''This is the subject of \citet{vaserstein1970stabilization}, published in 1970 and received 29 January 1969, hence predating the talk. \citet[\S\S1--2]{bakvavilov2000structure} gives the later standard elementary-group conventions.''',r'''standard stable hermitian \(K_1\); no unstated finite-rank stability theorem is attributed to the lecture.''',refs=['vaserstein1970stabilization','bakvavilov2000structure'],verification='publisher metadata checked',area='Hermitian K-theory')
item(246,'P000399','construction','Central extensions and a proposed simplicial higher hermitian theory',r'''Generators and relations lead to a Steinberg-type group and its kernel \(K_2O\); the notes connect universal central extensions with \(H_2\). They then outline a simplicial construction from triangular subgroups, writing higher groups as homotopy groups of the resulting object.''',r'''A perfect group has a universal central extension whose central kernel is its integral second homology. In stable linear \(K\)-theory, \(\operatorname{St}(A)\to E(A)\) realizes this construction. A simplicial union of cosets of triangular subgroups gives a Volodin-type model; homotopy groups refer to its realization, not to a discrete stable group. The notes do not give sufficient unitary root relations or simplicial data to verify an exact all-degree hermitian analogue for every form parameter.''',r'''The universal-extension theorem and the linear comparison are secure comparators. The final broad hermitian programme is retained as a partial identification, not promoted to a theorem proved by the later linear paper.''','F',r'''The linear construction was already published by Volodin in 1971 and is treated in \citet[\S6 and Chapter V]{vaserstein1976foundations}; the exact hermitian extension intended here was not identified. Vaserstein's 1973 comparison announcement explicitly concerns associative rings and ordinary linear \(K\)-theory.''',r'''the general mechanism is established, but the exact higher hermitian model announced in this compressed ending remains underdetermined.''',refs=['vaserstein1973foundations','vaserstein1976foundations'],literal='not determinable',match='partial',confidence='medium',area='Hermitian K-theory')
corr('P000396','last sentence, maximal form parameter',r'\(\Lambda_{\max}\): the quadratic form is recovered from \(|u|_q\)',r'Recovered from the hermitianized pairing \(b_q\), not from the diagonal refinement alone.',r'Scan inspected: the diagonal length symbol is present. For trivial involution, epsilon=-1 and Lambda=A, all lengths are zero but alternating pairings need not be zero.')
corr('P000397','hyperbolic scalar-product matrix',r'\(\left(\begin{smallmatrix}0&1\\-1&0\end{smallmatrix}\right)\)',r'For general symmetry use \(\left(\begin{smallmatrix}0&1\\\varepsilon&0\end{smallmatrix}\right)\), up to block order.',r'The preceding page fixes arbitrary epsilon. The displayed alternating matrix is only the epsilon=-1 specialization.')
corr('P000398','field example',r'\(K_0O(A)=\mathbb Z\) after the field cases epsilon=+/-1',r'Valid for the alternating case; symmetric forms require the field and its Witt theory.',r'Scan confirms the blanket Z. Over the real field positive and negative indices give Grothendieck-Witt group Z^2.')
corr('P000398','integral classification by dimension and signature','Dimension and signature classify forms over Z.','Separate stable classes from isometry classes and specify parity and definiteness.','Scan inspected. Positive definite even unimodular forms already supply distinct isometry classes with the same rank and signature.')
save()

